   File.WriteAllText(Path.Combine(folder,"returned.json"),await host.Plant.IntegrationAwait("(()=>{const p=window.__branchForge.trunkPreparation,m=p.model,b=window.__workflowBefore;if(m.id!==b.id||p.draft.id!==b.draft||m.name!==b.name)throw Error('Tree draft identity changed');if(m.images.length!==3||!m.materials[0].normal||!m.materials[0].occlusion||!m.materials[0].metallicRoughness||!m.material_editable?.base64)throw Error('Missing PBR or editable material');return {triangles:m.triangles,guides:m.guides,images:m.images.map(x=>x.name),materials:m.materials,calibration:m.calibration,source:m.source.sha256,parent:m.material_parent,workflow:m.material_workflow,draft:p.draft.id,asset:m.id,editableBytes:m.material_editable.bytes};})()",10000));
   await host.Plant.CaptureIntegration(Path.Combine(folder,"rig-inspection-ui.png"));
   string saved=await host.Plant.IntegrationAwait("(async()=>{const p=window.__branchForge.trunkPreparation,m=p.model;document.querySelector('#trunkPreparationDialog [data-project]').click();const deadline=Date.now()+20000;while(!(window.__branchForge.asset.authoring.imported_trunks?.assets||[]).some(a=>a.id===m.id&&a.source.sha256===m.source.sha256)){if(Date.now()>deadline)throw Error('Tree was not saved');await new Promise(r=>setTimeout(r,100));}return {saved:true,source:m.source.sha256,id:m.id,draft:p.draft.id};})()",25000);
   File.WriteAllText(Path.Combine(folder,"saved.json"),saved);
   // Restore from the saved same draft, including the portable bundle, then
   // revisit the material component. No decimation/unwrap is repeated.
   await host.Plant.IntegrationEvaluate("window.__resumeBefore={source:window.__branchForge.trunkPreparation.model.source.sha256,guides:JSON.stringify(window.__branchForge.trunkPreparation.model.guides)};document.querySelector('#trunkPreparationDialog [data-flow=material]').click();true");
   await Wait(async()=>!host.Busy&&await host.Material.IntegrationEvaluate("Boolean(window.treeMaterialIntegration?.state.current?.resume&&!window.treeMaterialIntegration.state.busy)")=="true",90000);
   File.WriteAllText(Path.Combine(folder,"resumed.json"),await host.Material.IntegrationEvaluate("({project:window.treeMaterialModule.getSnapshot(),state:window.treeMaterialIntegration.state})"));
   await host.Plant.IntegrationAwait("window.__branchForge.trunkPreparation.materialComponent.command('leave')",15000);
   await Task.Delay(500);
   await host.Plant.IntegrationEvaluate("document.querySelector('#trunkPreparationDialog [data-material-version]').click();true");
   await Wait(async()=>await host.Plant.IntegrationEvaluate("(()=>{const p=window.__branchForge.trunkPreparation;return !p.model.material_workflow&&p.panel.dataset.busy==='false'&&p.draft.id===window.__workflowBefore.draft&&p.model.source.sha256!==window.__resumeBefore.source;})()") == "true",20000);
   await host.Plant.IntegrationEvaluate("document.querySelector('#trunkPreparationDialog [data-material-version]').click();true");
   await Wait(async()=>await host.Plant.IntegrationEvaluate("(()=>{const p=window.__branchForge.trunkPreparation;return p.model.source.sha256===window.__resumeBefore.source&&p.panel.dataset.busy==='false';})()") == "true",20000);
   File.WriteAllText(Path.Combine(folder,"version-restore.json"),await host.Plant.IntegrationAwait("(()=>{const p=window.__branchForge.trunkPreparation;if(p.draft.id!==window.__workflowBefore.draft||JSON.stringify(p.model.guides)!==window.__resumeBefore.guides||!p.model.material_workflow.rigConfirmed)throw Error('Version restore lost session or confirmed guides');return {sameDraft:true,sameSource:true,sameGuides:true,rigConfirmed:true};})()",10000));
   File.WriteAllText(Path.Combine(folder,"phase.txt"),"saved-and-resumed");
   File.WriteAllText(Path.Combine(folder,"material-only.json"),await host.Material.IntegrationAwait(@"(async()=>{const api=window.treeMaterialModule,output=window.lastExport;if(!output?.model)throw Error('Missing final test model');const response=await fetch(output.model),bytes=await response.arrayBuffer(),parse=(await import('./model.js')).parseGLB,before=await parse(bytes,'OnlyMaterial.glb');const report=await api.prepareModel(bytes,'OnlyMaterial.glb',{height:10,target:15000,resolution:2048,padding:3,route:'material'}),mesh=window.treeLab.model,doc=api.getSnapshot();if(report.route!=='material'||!report.optimizationSkipped||mesh.indices.length!==before.indices.length||mesh.uvSHA256!==before.uvSHA256||doc.uvRevision!==0)throw Error('Material-only route changed geometry or UV');for(let i=0;i<mesh.indices.length;i++){const a=before.indices[i]*3,b=mesh.indices[i]*3;for(let k=0;k<3;k++)if(before.pos[a+k]!==mesh.pos[b+k])throw Error('Preserved face position changed');}return {passed:true,route:report.route,target:15000,input:report.inputTriangles,output:report.outputTriangles,uvPreserved:true,geometryPreserved:true};})()",180000));
   File.WriteAllText(Path.Combine(folder,"direct-rig.json"),await host.Plant.IntegrationAwait(@"(async()=>{const p=window.__branchForge.trunkPreparation,old=window.treeDuckMaterialIntegration.pending?.id,source=p.model.source,bytes=Uint8Array.from(atob(source.glb_base64),c=>c.charCodeAt(0));await p.importFile(new File([bytes],'DirectRig.glb',{type:'model/gltf-binary'}),{route:'rig'});if(p.draft.preparationRoute!=='rig'||p.panel.querySelector('[data-next]').disabled)throw Error('Direct rig choice not applied');p.panel.querySelector('[data-next]').click();const deadline=Date.now()+90000;while(p.autoState!=='preview'){if(Date.now()>deadline)throw Error('Direct rig did not analyze');await new Promise(r=>setTimeout(r,100));}if(window.treeDuckMaterialIntegration.pending?.id!==old||p.model.source.sha256!==source.sha256)throw Error('Direct rig invoked material or changed source');p.panel.querySelector('[data-auto-discard]').click();return {passed:true,materialSkipped:true,sourcePreserved:true,route:p.draft.preparationRoute};})()",100000));
   File.WriteAllText(Path.Combine(folder,"result.json"),json.Serialize(new {passed=true,windowsVisible=false,backend="D3D12",singleWindow=true,plantProjectFormat=4,materialProjectFormat=25,roundTrip=true,sameDraft=true,automaticSkeletonCandidate=true,rigConfirmed=true,editableMaterialRestored=true,versionRoundTrip=true,unsavedMaterialResumed=true,threeImportRoutes=true,materialOnlyPreserved=true,directRigSkippedMaterial=true,finalModelPresentation=true}));host.SelectPlant();host.Close();
  }catch(Exception error){File.WriteAllText(Path.Combine(folder,"result.json"),json.Serialize(new {passed=false,error=error.ToString(),windowsVisible=false}));ReportFailure(host,folder);}
  }
  internal static async Task RunClose(Workspace host){
   string folder=Path.Combine(host.Root,".runtime","integration-test"),report=Path.Combine(folder,"component-close-result.json"),phase="startup";var json=new JavaScriptSerializer();
   try{
    var prepared=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(folder,"prepared.json")));var project=(Dictionary<string,object>)prepared["project"];string projectId=Convert.ToString(project["id"]);
    await Wait(()=>Task.FromResult(host.Plant.IntegrationReady),90000);
    phase="import";File.WriteAllText(Path.Combine(folder,"close-phase.txt"),phase);
    await host.Plant.IntegrationAwait("(async()=>{const p=window.__branchForge.trunkPreparation;await p.open();const r=await fetch('/api/material-handoff?id=11111111-1111-4111-8111-111111111111');await p.importFile(new File([await r.arrayBuffer()],'组件验收树干.glb'));return true;})()",60000);
    host.OpenMaterial();await Wait(()=>Task.FromResult(host.Material.IntegrationReady),90000);
    phase="restore";File.WriteAllText(Path.Combine(folder,"close-phase.txt"),phase);
    await host.Material.IntegrationAwait("window.treeMaterialIntegration.receive("+json.Serialize(new {id=Guid.NewGuid().ToString(),projectId=projectId,name="组件验收树干.glb",stage="material"})+")",90000);
    if(!host.SingleWorkflowFrame)throw new Exception("Not mounted inside the trunk workflow");
    foreach(string stage in new[]{"model","material","export"}){phase=stage;File.WriteAllText(Path.Combine(folder,"close-phase.txt"),phase);await host.Plant.IntegrationAwait("window.__branchForge.trunkPreparation.materialComponent.command('stage',"+json.Serialize(stage)+")",60000);await Wait(async()=>await host.Material.IntegrationEvaluate("document.body.dataset.workspaceStage==="+json.Serialize(stage))=="true",10000);}
    await host.Material.IntegrationAwait("window.treeMaterialModule.setView({version:1,eye:[4,8,7],target:[1,2,3],fov:36})",10000);
    phase="leave";File.WriteAllText(Path.Combine(folder,"close-phase.txt"),phase);await host.Plant.IntegrationAwait("window.__branchForge.trunkPreparation.materialComponent.command('leave')",20000);
    await host.Plant.IntegrationAwait("(()=>{const v=window.__branchForge.trunkPreparation.view.getView();if(v.target.some((n,i)=>Math.abs(n-[1,2,3][i])>.0001))throw Error('Camera focus was reset');return true;})()",10000);
    File.WriteAllText(report,json.Serialize(new {passed=true,componentMounted=true,outerNavigation=true,cameraFocusPreserved=true,closing=true,windowsVisible=false}));
   }catch(Exception error){File.WriteAllText(report,json.Serialize(new {passed=false,phase=phase,error=error.ToString()}));}
   host.SelectPlant();host.Close();await Task.Delay(25000);
   if(!host.IsDisposed){File.WriteAllText(report,json.Serialize(new {passed=false,error="Component did not confirm close"}));System.Windows.Forms.Application.ExitThread();}
  }
  internal static async Task RunRigTransfer(Workspace host){
   string fixture=Path.Combine(host.Root,".runtime","integration-test"),folder=Path.Combine(host.Root,".runtime","rig-transfer-test"),phase="startup";Directory.CreateDirectory(folder);var json=new JavaScriptSerializer();
   try{
    var prepared=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(fixture,"prepared.json")));var project=(Dictionary<string,object>)prepared["project"];
    var saved=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(fixture,"independent-result-check.json")));var returned=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(fixture,"returned.json")));var workflow=(Dictionary<string,object>)returned["workflow"];
    var checkpoint=new {key=workflow["checkpointKey"],projectId=workflow["projectId"],finalSHA256=workflow["finalSHA256"],bundleSHA256=workflow["bundleSHA256"]};
    string model="/"+Convert.ToString(saved["outputDirectory"]).Substring("material/".Length)+"/"+Convert.ToString(saved["glb"]);
    await Wait(()=>Task.FromResult(host.Plant.IntegrationReady),90000);phase="import";
    await host.Plant.IntegrationAwait(@"(async()=>{const p=window.__branchForge.trunkPreparation;await p.open();const r=await fetch('/api/material-handoff?id=11111111-1111-4111-8111-111111111111');if(!r.ok)throw Error('Missing owned GLB fixture');await p.importFile(new File([await r.arrayBuffer()],'骨架转接验收.glb'));window.__rigDraft=p.draft.id;return true;})()",60000);
    await host.Plant.IntegrationAwait("(async()=>{const p=window.__branchForge.trunkPreparation,{materialGeometryKey,digest}=await import('./trunk-material-workflow.js'),origin={id:p.model.id,geometry:await materialGeometryKey(p.model),calibration:p.model.calibration},originKey=await digest(new TextEncoder().encode(JSON.stringify({sessionId:p.draft.id,...origin})));await p.noteMaterialSession({projectId:"+json.Serialize(project["id"])+",originKey,preparation:'full'},{sessionId:p.draft.id});p.panel.querySelector('[data-flow=material]').click();return true;})()",20000);
    phase="restore-saved-material";await Wait(()=>Task.FromResult(host.Material!=null&&host.Material.IntegrationReady),90000);await Wait(async()=>!host.Busy&&await host.Material.IntegrationEvaluate("Boolean(window.treeMaterialIntegration?.state.current&&!window.treeMaterialIntegration.state.busy)")=="true",90000);
    phase="install-cached-export";
    // Focus on transport of an already baked GLB, using the real saved fixture.
    await host.Material.IntegrationAwait("(()=>{const real=window.treeMaterialModule;window.treeMaterialModule={...real,exportFinalGLB:async()=>({model:"+json.Serialize(model)+"}),checkpoint:async()=>("+json.Serialize(checkpoint)+")};return true;})()",10000);
    phase="install-display-timeout";await host.Plant.IntegrationAwait("(()=>{const v=window.__branchForge.trunkPreparation.view;window.__normalRigPresentation=v.waitForPresentation;v.waitForPresentation=o=>window.__normalRigPresentation({...o,timeout:0,required:false});return true;})()",10000);
    phase="click-next";await host.Plant.IntegrationAwait("window.__branchForge.trunkPreparation.materialComponent.command('stage','export')",15000);await host.Plant.IntegrationAwait("window.__branchForge.trunkPreparation.materialComponent.command('next')",15000);
    await Wait(async()=>!host.Busy&&!host.MaterialActive&&await host.Plant.IntegrationEvaluate("Boolean(window.__trunkFinalPresentation&&window.__branchForge.trunkPreparation.model?.material_workflow?.checkpointKey)")=="true",90000);
    phase="verify-timeout-keeps-rig";File.WriteAllText(Path.Combine(folder,"accepted.json"),await host.Plant.IntegrationAwait("(()=>{const p=window.__branchForge.trunkPreparation,r=window.__trunkFinalPresentation;if(!r.presentationTimedOut||r.displayError||p.draft.id!==window.__rigDraft||p.materialComponent.active||p.model.source.sha256!=="+json.Serialize(saved["glbSHA256"])+")throw Error('Display timeout rolled back or damaged saved model');return {source:p.model.source.sha256,draft:p.draft.id,presentation:r};})()",10000));
    await Wait(async()=>await host.Plant.IntegrationEvaluate("window.__branchForge.trunkPreparation.autoState==='preview'")=="true",90000);
    phase="actual-static-refresh";File.WriteAllText(Path.Combine(folder,"refresh.json"),await host.Plant.IntegrationAwait("(async()=>{const p=window.__branchForge.trunkPreparation;p.view.waitForPresentation=window.__normalRigPresentation;const frames=[];for(let i=0;i<3;i++){const results=await Promise.all(Array.from({length:3},()=>p.view.waitForPresentation({timeout:15000})));for(const r of results){if(!r.presentationReady||r.displayError||r.source!==p.model.source.sha256)throw Error('Saved model did not present on retry');frames.push({revision:r.native.revision,frames:r.native.frames,source:r.source});}}if(frames[3].revision<=frames[0].revision||frames[6].revision<=frames[3].revision)throw Error('Static refresh did not demand a new actual frame');return {passed:true,requests:frames.length,frames};})()",60000));
    if(host.MaterialActive||host.ResultTransitionVisible)throw new Exception("Returned to export or left transition cover visible");
    if(await host.Material.IntegrationEvaluate("Boolean(window.treeMaterialIntegration.state.busy||window.treeMaterialIntegration.state.awaiting)")=="true")throw new Exception("Material handoff was not acknowledged");
    await host.Plant.IntegrationAwait("(()=>{const p=window.__branchForge.trunkPreparation;p.panel.querySelector('[data-auto-discard]').click();return true;})()",10000);
    phase="normal-button-return";await host.Plant.IntegrationAwait("(()=>{const p=window.__branchForge.trunkPreparation;p.panel.querySelector('[data-flow=export]').click();return true;})()",10000);
    await Wait(async()=>host.MaterialActive&&!host.Busy&&await host.Material.IntegrationEvaluate("Boolean(window.treeMaterialIntegration.state.current?.resume&&!window.treeMaterialIntegration.state.busy)")=="true",90000);
    await host.Plant.IntegrationAwait("(()=>{delete window.__trunkFinalPresentation;return true;})()",10000);
    await host.Plant.IntegrationAwait("window.__branchForge.trunkPreparation.materialComponent.command('next')",15000);
    await Wait(async()=>!host.Busy&&!host.MaterialActive&&await host.Plant.IntegrationEvaluate("Boolean(window.__trunkFinalPresentation?.presentationReady)")=="true",90000);
    File.WriteAllText(Path.Combine(folder,"normal-return.json"),await host.Plant.IntegrationAwait("(()=>{const p=window.__branchForge.trunkPreparation,r=window.__trunkFinalPresentation;if(p.draft.id!==window.__rigDraft||p.materialComponent.active||r.source!=="+json.Serialize(saved["glbSHA256"])+"||r.displayError)throw Error('Normal button return did not preserve final model');return {passed:true,source:r.source,presentationReady:r.presentationReady,revision:r.native.revision};})()",10000));
    File.WriteAllText(Path.Combine(folder,"result.json"),json.Serialize(new {passed=true,cachedFixtureUsed=true,pbrRebaked=false,realNextCommand=true,keptRigAfterDisplayTimeout=true,normalButtonReturn=true,staticRefreshRequests=9,actualD3D12Presentation=true,source=saved["glbSHA256"],windowsVisible=false}));
   }catch(Exception error){File.WriteAllText(Path.Combine(folder,"result.json"),json.Serialize(new {passed=false,phase=phase,error=error.ToString(),windowsVisible=false}));}
   host.SelectPlant();host.Close();await Task.Delay(25000);if(!host.IsDisposed){File.WriteAllText(Path.Combine(folder,"result.json"),json.Serialize(new {passed=false,phase=phase,error="Rig transfer test did not close normally"}));System.Windows.Forms.Application.ExitThread();}
  }
  static async void ReportFailure(Workspace host,string folder){try{if(host.Material!=null&&host.Material.IntegrationReady)File.WriteAllText(Path.Combine(folder,"failure-detail.json"),await host.Material.IntegrationEvaluate("({message:document.querySelector('[data-trunk-message]')?.textContent,current:window.treeMaterialIntegration?.state,lastExport:window.lastExport?.model,toasts:[...document.querySelectorAll('[role=status],.toast')].map(e=>e.textContent).filter(Boolean)})"));}catch{}host.SelectPlant();host.Close();}
 }
